scripts.醉郎中.txt:
//和醉郎中对话

	If ($Talkzuilangzhong == 0) @Talk0;
	If ($Talkzuilangzhong == 1) @Talk1;
	If ($Talkzuilangzhong == 2) @Talk3;
	
@Talk0:
	Say("醉郎中：酒，酒啊——给我酒……");
	Say("独孤剑：这位大哥，你醉了。", 2);
	Say("醉郎中：酒，酒——");
	SetNpcDir("店小二",3);
	Say("店小二：客官，你不用管他了。他在这里喝了一整天，谁也弄不走他。");
	SetPlayerDir(0);
	Say("独孤剑：伙计，这是怎么回事。", 1);
	Say("店小二：小的也不知道呀。这人自称是个什么郎中，昨天到这里来喝了个死醉。嘴里尽嘟囔些什么“丢了药方”、“宝贝”什么的，莫名其妙……");
	Say("独孤剑：丢了药方……", 8);
	Say("店小二：对呀！没听说过郎中丢了张药方会愁成这样的——这年头，庸医……");
	SetNpcDir("店小二",0);
	Assign($Talkzuilangzhong, 1);
	Assign($Sub, 120);
	Return;
	
@Talk1:
	If ($Sub == 150) @Sub150;
	
	Say("醉郎中：完咯，完咯……我的方子……");
	Return;
	
  @Sub150:
	Say("醉郎中：完咯，完咯……方子啊……");
	
	Choose("独孤剑：这个郎中真有些古怪……","A 归还药方","B 不归还", $Choose);
	If ($Choose == 0) @Choose0;
	If ($Choose == 1) @Choose1;
	
   @Choose0:
	Say("独孤剑：这位大哥，你丢的可是这张药方？", 1);
	Say("醉郎中：药方！药方在哪，在哪——");
	Say("独孤剑：是不是这张？", 1);
	Say("醉郎中：啊——就是，就是！太好了，太好了——");
	Say("独孤剑：现在物归原主……", 1);
	Say("醉郎中：兄……弟，太好了——这些银子算兄弟的一点心意！");
	Say("从醉郎中那意外的得到白银二千两。");
	Assign($Talkzuilangzhong, 2);
	DelGoods("Goods411_一张药方.ini");
	AddMoney(2000);
	Say("独孤剑：这……",6);
	Return;
	
   @Choose1:
   	Say("独孤剑：这里有些蹊跷，还是先不要还给他的好。", 8);
   	Return;
   	
@Talk3:
	Say("醉郎中：你没有看过药方罢……");
	Return;

scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap016hemei == 0) @Talk0;
	If ($Talkmap016hemei == 1) @Talk1;
	If ($Talkmap016hemei == 2) @Talk2;
	If ($Talkmap016hemei == 3) @Talk3;
	Return;
@Talk0:	
	Say("何梅：独孤公子是哪里人？", 66);
	Say("独孤剑：我自幼父母双亡，被师傅带回衡山抚育成人。", 1);
	Assign($Talkmap016hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子可有兄弟姊妹？", 66);
	Say("独孤剑：我有许多同门学艺的师弟师妹。", 1);
	Assign($Talkmap016hemei, 2);
	Return;
@Talk2:	
	Say("何梅（害羞的）：独孤公子是否……是否已成家立室？", 66);
	Say("独孤剑：我乃一江湖草莽之人，过着一种刀光剑影、四处飘摇的生活，寻常女子怎愿与我相伴？况且我也不想误人青春。", 1);
	Say("何梅：……", 66);
	Assign($Talkmap016hemei, 3);
	Return;
@Talk3:	
	Say("独孤剑：何姑娘家住哪里？", 1);
	Say("何梅：我家住在城北，就在官衙的后面。", 66);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap017jia == 0) @Talk0;
	If($Talkmap017jia == 1) @Talk1;
	If($Talkmap017jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap017jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap017jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.酒客组1对话.txt:
// 与酒客组1对话

	If ($Event == 50) @Event50; 
	If ($Event == 180) @Event180; 

	If ($Jiuke1 == 0) @Talk0;
	If ($Jiuke1 == 1) @Talk1;
	If ($Jiuke1 == 2) @Talk2;
	If ($Jiuke1 == 3) @Talk3;
	If ($Jiuke1 == 4) @Talk4;
		
@Talk0:	
	Say("酒客刘威：听说金国宰相挞懒前些天被人刺杀了。", 0);
	Say("酒客杨刚：这事我也听说了，快哉，快哉！", 0);
	Say("酒客刘威：说不准是中原武林中人干的呢，不过有这能耐的高手好象没几个。", 0);
	Say("酒客杨刚：说到武林人士，鼎鼎有名的武夷山“沧浪剑客”柳中原柳老爷子这几天好象到了临安，只是这种高人很难见到。", 0);
	Say("酒客刘威：过几天就是柳老爷子的六十大寿，江湖朋友都要去庆贺，那排场一定很阔气。", 0);
	Say("酒客杨刚：我们也去瞧瞧热闹？", 0);
	Assign($Jiuke1, 1);
	Return;
@Talk1:
	Say("酒客刘威：皇上和那些大官只知道花天酒地，要不是岳爷和韩爷在前方拼命，这江山只怕早就断送在金人手里了。", 0);
	Say("酒客杨刚：兄弟，这话可不能乱讲，传出去我们的脑袋就要搬家了。", 0);
	Say("酒客刘威：老子有一说一，有二说二，怕他个鸟。", 0);
	Say("酒客杨刚：来来来，喝酒喝酒。", 0);
	Assign($Jiuke1, 2);
	Return;
@Talk2:
	Say("酒客刘威：韩元帅的夫人粱红玉智勇双全，真乃巾帼英豪也。", 0);
	Say("酒客杨刚：是啊，真教我等须眉汗颜。", 0);
	Assign($Jiuke1, 3);
	Return;	
@Talk3:
	Say("酒客刘威：现在我们有岳家军和韩家军驻守边关，怕他金狗干什么？只可惜朝中有人乱政，否则岳爷爷早就收复燕京了。", 0);
	Say("酒客杨刚：这里耳目众多，说话小心些。", 0);
	Say("酒客刘威：来来来，喝酒喝酒。", 0);
	Assign($Jiuke1, 4);
	Return;	
@Talk4:
	Say("酒客杨刚：这里耳目众多，说话小心些。", 0);
	Say("酒客刘威：来来来，喝酒喝酒。", 0);
	Return;		
	
@Event50:	
	Say("酒客刘威：青天白日就有强人出没，这年月真是……", 0);
	Say("酒客杨刚：不知是谁家的女儿，又被糟蹋了一个，唉。", 0);
    Return;		
	
@Event180:	
	Say("酒客刘威：听说衡山派掌门刘轻舟前不久被一伙来历不明的高手伏击伤重而死，他的大弟子独孤剑做了新掌门人，这件事在江湖上穿得沸沸扬扬。", 0);
	Return;

scripts.酒客组2对话.txt:
// 与酒客组2对话

	If ($Event == 50) @Event50; 
	If ($Event == 180) @Event180; 

	If ($Jiuke2 == 0) @Talk0;
	If ($Jiuke2 == 1) @Talk1;
		
@Talk0:	
	Say("酒客赵顺顺：张风张大人一向清明廉正，执法严明，不知这次为何久久不能捕获采花大盗？", 0);
	Say("酒客徐大毛：张大人和“沧浪剑客”柳老爷子是至交，柳老爷子寿辰之前突然下山，说不准就来帮张大人处理这件事的。", 0);
	Say("酒客赵顺顺：但愿他们早日捕获采花大盗。", 0);
	Say("酒客徐大毛：这两位高手联手，再厉害的盗贼也会手到擒来。", 0);
	Assign($Jiuke2, 1);
	Return;
@Talk1:
	Say("酒客赵顺顺：听说前些日子柳中原来过这里。", 0);
	Say("酒客徐大毛：谁都知道柳中原和张风张大人是老交情了。", 0);
	Return;
	
@Event50:	
	Say("酒客赵顺顺：那女孩刚到门口，一黑衣人从天而降，眨眼间两人就不见了。", 0);
	Say("酒客徐大毛：凭我这三脚猫功夫，连那采花大盗是怎样抓人的都没看清，更不用说去追杀他了。", 0);
	Say("酒客赵顺顺：那人功夫了得，不象寻常黑道上的人物。", 0);
	Return;		

@Event180:	
	Say("酒客赵顺顺：听说一个很年轻的武林高手除掉了碧霞岛上的采花大盗，传说这人就是衡山的新任掌门独孤剑。", 0);
	Say("酒客徐大毛：真是后生可畏啊！", 0);
	Return;

