scripts.路达及其跟班死亡.txt:
// 独孤剑和张如梦不打不相识，结识方勉

	Add($map017Enemy, 1);
	If ($map017Enemy == 4) @finished;
    Return;
    
@finished:
	FadeOut();
	StopMusic();
	PlayMusic("闲步.mp3");
	SetNpcKind("张如梦1", 1);
	SetNpcRelation("张如梦1", 2);
	LoadNpc("map017_win.npc");
	LoadObj("map017_win.obj");
	SetPlayerPos(6, 18);
	SetPlayerDir(1);
	SetPlayerScn();
	SetPlayerState(0);
	SetNpcPos("张如梦1", 5, 19);
	SetNpcDir("张如梦1", 5);
	SetNpcDir("方勉",3);
	Say("路达：有种的别跑！大爷回头来收拾你！", 0);
	ClearEffect();
	FadeIn();
	
	Say("张如梦：真痛快！对这种连祖宗都忘记的人，早就应该好好教训一番了！", 12);
	Say("独孤剑：在下衡山独孤剑，请教公子姓名？", 2);
	Say("张如梦：在下张如梦。", 11);
	Say("独孤剑：张公子刚才骂得好痛快！", 2);
	Say("张如梦：彼此彼此。", 12);
	Say("独孤剑：哈哈哈哈！", 2);
	Say("张如梦：哈哈哈哈！正所谓是不打不相识，独孤兄是第一次来临安吧？", 12);
	Say("独孤剑：正是，听说临安近来有采花贼出没，却不知是真是假？", 1);
	Say("张如梦：是有此事，而且采花贼武功高超，并非一般采花贼，其中更有古怪。", 11);
	Say("独孤剑：什么古怪？", 8);
	Say("张如梦：采花贼专找穿绿衣的少女下手，目的仿佛是针对张大人。", 11);
	Say("独孤剑：何出此言？", 8);
	Say("张如梦：因为张大人的女儿平时最喜欢穿绿色衣衫，在临安有“碧波凌风”之称，所以采花贼看来是醉翁之意不在酒。", 11);
	Say("独孤剑：采花贼为何要如此做呢？", 8);
	Say("张如梦：这也是我想知道的。", 11);
	
	NpcGoto("方勉", 5, 20);
	SetNpcDir("方勉", 5);
	Say("中年人：果真是自古英雄出少年啊！", 50);
	NpcGoto("张如梦1", 5, 17);
	SetNpcDir("张如梦1", 0);
	NpcGoto("方勉", 5, 19);
	SetNpcDir("方勉", 5);
	Say("中年人：你叫独孤剑？", 50);
	Say("独孤剑：是的。", 1);
	Say("中年人：你是衡山刘轻舟的弟子？", 50);
	Say("独孤剑：不错。", 1);
	Say("中年人：他最近好吗？", 50);
	Say("独孤剑：家师不幸为贼人所害。", 9);
	Say("中年人：唉，可惜！", 50);
	Say("独孤剑：……", 1);
	Watch("张如梦1", "方勉", 0);
	Say("中年人：你叫张如梦？", 50);
	Say("张如梦：是的。", 11);
	Say("中年人：你父亲是谁？", 50);
	Say("张如梦：你问来问去，问这问那，你又是谁？", 11);
	Say("中年人：在下方勉。", 50);
	Say("独孤剑（暗忖）：原来他就是“天心飞仙”四剑客中号称“心剑客”的方勉。", 1);
	Say("方勉：张如梦，你是来救你父亲的，还是来杀你父亲的？", 50);
	Say("张如梦：天作虐，尤可恕；自作虐，不可活。这世上谁能救他？但这事和你又有何干系？别人敬仰你是武林泰斗，可我眼中你不过是个沽名钓誉之徒。", 11);
	Say("方勉：哼，竟敢在老夫面前出言不逊，不怕老夫一剑杀了你？", 53);
	Say("张如梦：方大侠只管动手便是，这样正好让江湖上知道方大侠的真面目，一个心胸狭隘的伪君子！", 11);
	Say("方勉：哈哈！哈哈哈！好好好，骂得好，骂得好！", 51);
	SetPlayerDir(7);
	NpcGoto("方勉", 6, 21);
